#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 4) {
        printf("NO_INPUT\n");
        return 0;
    }
    long long base = strtoll(argv[1], NULL, 10);
    long long exponent = strtoll(argv[2], NULL, 10);
    long long modulus = strtoll(argv[3], NULL, 10);
    if (exponent < 0) {
        printf("NEGATIVE_EXPONENT\n");
        return 0;
    }
    if (modulus < 1 || modulus > 1000000000) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    if (modulus == 1) {
        printf("BAD_MODULUS\n");
        return 0;
    }
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1) {
            result = (result * base) % modulus;
        }
        base = (base * base) % modulus;
        exponent /= 2;
    }
    printf("result=%lld\n", result);
    return 0;
}
